const CustomerAuth=function(){const TOKEN_KEY="skiri_customer_token";const PROFILE_KEY="skiri_customer_profile";const LAST_EMAIL_KEY="skiri_last_email";function saveSession(token,customer){try{localStorage.setItem(TOKEN_KEY,token);localStorage.setItem(PROFILE_KEY,JSON.stringify(customer));if(customer&&customer.email)localStorage.setItem(LAST_EMAIL_KEY,String(customer.email))}catch(e){}}function getToken(){try{return localStorage.getItem(TOKEN_KEY)}catch(e){return null}}function getCustomer(){try{return JSON.parse(localStorage.getItem(PROFILE_KEY))}catch(e){return null}}function isLoggedIn(){return!!getToken()}function clearSession(){try{localStorage.removeItem(TOKEN_KEY);localStorage.removeItem(PROFILE_KEY)}catch(e){}}function getRememberedEmail(){try{return localStorage.getItem(LAST_EMAIL_KEY)||""}catch(e){return""}}function forgetEmail(){try{localStorage.removeItem(LAST_EMAIL_KEY)}catch(e){}}const LOGOUT_NETWORK_GRACE_MS=1500;async function logout(){const token=getToken();clearSession();if(token){try{await Promise.race([Api.post("logoutCustomer",{token:token}).catch(function(){}),new Promise(function(resolve){setTimeout(resolve,LOGOUT_NETWORK_GRACE_MS)})])}catch(e){}}}async function guardCustomerAuth(redirectTo){const dest=redirectTo||"customer-login.html";const token=getToken();if(!token){window.location.href=dest;return null}const res=await Api.post("getCustomerProfile",{token:token});if(!res.ok){clearSession();window.location.href=dest+"?expired=1";return null}saveSession(token,res.customer);return res.customer}return{saveSession:saveSession,getToken:getToken,getCustomer:getCustomer,isLoggedIn:isLoggedIn,clearSession:clearSession,logout:logout,guardCustomerAuth:guardCustomerAuth,getRememberedEmail:getRememberedEmail,forgetEmail:forgetEmail}}();